import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../Core/Resources/app_constants.dart';import '../../../../Config/Routes/route_name.dart';import '../../../../main.dart';import '../../../../Core/Resources/app_colors.dart';import 'package:convex_bottom_bar/convex_bottom_bar.dart';import 'package:flutter/material.dart';import '../manager/main_cubit.dart';class BuildBottomNavigationBar extends StatelessWidget {  final Key scanKey;  const BuildBottomNavigationBar({    super.key,    required this.scanKey,  });  @override  Widget build(BuildContext context) {    return ConvexAppBar(      elevation: 5,      color: AppColors.grayscale70,      activeColor: AppColors.primaryColor,      backgroundColor: AppColors.backgroundColor,      style: TabStyle.fixedCircle,      initialActiveIndex: context.watch<MainCubit>().state,      onTabNotify: (index) {        if (index == 2) {          kNavigationService.navigateTo(AppRoutes.authentication);          return false;        }        return true;      },      items: AppConstants.itemsNavBar(context: context, scanKey: scanKey),      onTap: (int i) {        if (i == 2) {          kNavigationService.navigateTo(AppRoutes.authentication);        } else {          context.read<MainCubit>().changeIndex(i);        }      },    );  }}